MATCH (a:PlantItem {tag: 'H-25501'}), (b:PlantItem {tag: 'EA-25501'})
RETURN a.tag AS from_tag, b.tag AS to_tag,
       EXISTS {
         MATCH (a) ((x:PlantItem)-[:line_to]->(y:PlantItem)
           WHERE x.tag <> 'R-25501' AND y.tag <> 'R-25501')+ (b)
       } AS reachable_without_R

